SELECT p.post_id AS postId, p.user_id AS userId, u.nickname AS nickname, AS profileImageId, p.title AS title, p.content AS content, AS thumbnailImageId, AS imageCount, p.is_spoiler AS isSpoiler, p.view_count AS viewCount, p.like_count AS likeCount, p.comment_count AS commentCount, p.created_at AS createdAt FROM community_post p JOIN user u ON u.user_id = p.user_id WHERE p.series_id = #{seriesId} AND p.deleted_at IS NULL
AND p.post_id < #{lastId}
ORDER BY p.post_id DESC LIMIT #{size}

SELECT p.post_id AS postId, p.user_id AS userId, u.nickname AS nickname, AS profileImageId, p.title AS title, p.content AS content, AS thumbnailImageId, AS imageCount, p.is_spoiler AS isSpoiler, p.view_count AS viewCount, p.like_count AS likeCount, p.comment_count AS commentCount, p.created_at AS createdAt, COALESCE(pl.periodCnt, 0) AS periodLikeCount FROM community_post p JOIN user u ON u.user_id = p.user_id LEFT JOIN (SELECT post_id, COUNT(*) AS periodCnt FROM community_post_like WHERE created_at >= #{periodStart} GROUP BY post_id) pl ON pl.post_id = p.post_id WHERE p.series_id = #{seriesId} AND p.deleted_at IS NULL
AND ( COALESCE(pl.periodCnt, 0) < #{lastValue} OR (COALESCE(pl.periodCnt, 0) = #{lastValue} AND p.post_id < #{lastId}) )
ORDER BY periodLikeCount DESC, p.post_id DESC LIMIT #{size}
